def inplane_axis(member):
    """Independent local-y direction from raw coordinates (in-plane, unrotated).

    Returns None for vertical members (not exercised here), mirroring T().
    """
    i, j = member.i_node, member.j_node
    x = np.array([j.X - i.X, j.Y - i.Y, j.Z - i.Z])
    x = x / np.linalg.norm(x)
    if abs(x[1]) > 1.0 - 1e-9:
        return None  # vertical member (not used in these models)
    if abs(x[0]) < 1e-12 and abs(x[2]) < 1e-12:
        return None
    if abs(x[1]) < 1e-12:
        # horizontal member: T() fixes the local y-axis to global Y
        return x, np.array([0.0, 1.0, 0.0]), np.cross(x, np.array([0.0, 1.0, 0.0]))
    proj = np.array([x[0], 0.0, x[2]])
    z = np.cross(proj, x) if j.Y > i.Y else np.cross(x, proj)
    z = z / np.linalg.norm(z)
    y = np.cross(z, x)
    return x, y, z

