import json

base = json.load(open('/tmp/digest_baseline.json'))
fixed = json.load(open('/tmp/digest_fixed.json'))

def flat(d, p=''):
    out = {}
    for k, v in d.items():
        if isinstance(v, dict):
            out.update(flat(v, f'{p}/{k}'))
        elif isinstance(v, list):
            out[f'{p}/{k}'] = tuple(json.dumps(x) for x in v) if v and isinstance(v[0], (list, dict)) else tuple(v)
        else:
            out[f'{p}/{k}'] = v
    return out

fb, ff = flat(base), flat(fixed)
diff = {k for k in set(fb) | set(ff) if fb.get(k) != ff.get(k)}
by_model = {}
for k in sorted(diff):
    model = k.split('/')[0]
    by_model.setdefault(model, []).append(k)
for model, ks in by_model.items():
    print(f"--- {model}: {len(ks)} differing entries")
    for k in ks[:60]:
        print("   ", k)
print("total differing leaf entries:", len(diff))
